options(stringsAsFactors=FALSE,scipen=5)
B<-"__LEGACY_ROOT__/outputs/SSI_Prevention_Intelligence/SSI_Inferential_Microbiology_Figures"
T<-file.path(B,"tables/microbiology");P<-file.path(B,"individual_vector_pdfs")
rd<-function(f)read.csv(file.path(T,f))
d<-rd("national_ssi_pathogens.csv");en<-rd("category_enrichment_tests.csv");po<-rd("pooled_category_enrichment_tests.csv")
age<-rd("adult_pediatric_pathogen_tests.csv");dp<-rd("national_ssi_pathogens_by_depth.csv");dt<-rd("depth_pathogen_tests.csv")
amr<-rd("national_ssi_amr.csv");oc<-rd("amr_occurrence_priority_rounding_bounds.csv");tot<-rd("national_ssi_source_totals.csv")
rep<-rd("cross_period_pathogen_signal_replication.csv");rep<-rep[tolower(rep$taxonomy_stable)=="true",];period<-rd("period_shift_tests.csv");depperiod<-rd("depth_period_tests.csv")
BLUE<-"#2476B5";RED<-"#CE2635";GREEN<-"#229B86";ORANGE<-"#ED7800";PURPLE<-"#7956A8";INK<-"#162332";LIGHT<-"#F1F3F5";GREY<-"#777777"
fmt<-function(x)format(round(x),big.mark=",",scientific=FALSE,trim=TRUE)
ps<-function(x)if(!length(x)||!is.finite(x[1]))"NE"else if(x[1]<.001)"<0.001"else paste0("=",sprintf("%.3f",x[1]))
short<-function(p){x<-c("Staphylococcus aureus"="S. aureus","Escherichia coli"="E. coli","Enterococcus faecalis"="E. faecalis","Enterococcus faecium"="E. faecium","Pseudomonas aeruginosa"="P. aeruginosa","Coagulase-negative staphylococci"="CoNS","Candida albicans"="C. albicans","Selected Klebsiella spp"="Selected Klebsiella","Enterobacter spp"="Enterobacter","Bacteroides spp"="Bacteroides","Candida glabrata"="C. glabrata","Other Candida spp"="Other Candida","Acinetobacter spp"="Acinetobacter");z<-unname(x[p]);z[is.na(z)]<-p[is.na(z)];z}
openpdf<-function(i,name,w=15,h=10){pdf(file.path(P,sprintf("Figure_%02d_%s.pdf",i,name)),width=w,height=h,family="Helvetica",useDingbats=FALSE);par(family="Helvetica",col=INK,col.axis=INK,col.lab=INK,fg=INK,bty="l",las=1,mgp=c(2.3,.6,0),tcl=-.2)}
empty<-function(x=c(0,1),y=c(0,1)){plot.new();plot.window(xlim=x,ylim=y,xaxs="i",yaxs="i")}
hf<-function(h,f){mtext(h,3,outer=TRUE,line=.7,adj=0,font=2,cex=1.1);mtext(f,1,outer=TRUE,line=.7,adj=0,cex=.66)}
forest<-function(z,title,labels,xlim=c(.25,8),note="Exploratory pathogen-report share ratios; BH q"){
 par(mar=c(4.5,9,3.3,5),cex=.85,xpd=FALSE)
 plot(1,0,type="n",log="x",xlim=xlim,ylim=c(.5,nrow(z)+1),yaxt="n",ylab="",xlab="Pathogen-report share ratio (95% CI)",main=title,cex.main=.94);abline(v=1,lty=2,col=GREY)
 for(i in 1:nrow(z)){yy<-nrow(z)+1-i;segments(max(xlim[1],z$ratio_lower[i]),yy,min(xlim[2],z$ratio_upper[i]),yy,col=BLUE,lwd=1.2);points(max(xlim[1],min(xlim[2],z$report_share_ratio[i])),yy,pch=16,col=BLUE,cex=.7);if(z$ratio_lower[i]<xlim[1])arrows(xlim[1]*1.15,yy,xlim[1],yy,length=.05,col=BLUE);if(z$ratio_upper[i]>xlim[2])arrows(xlim[2]/1.15,yy,xlim[2],yy,length=.05,col=BLUE);text(10^par("usr")[1]/1.03,yy,labels[i],adj=1,cex=.70,xpd=NA);text(10^par("usr")[2]*1.04,yy,paste0(sprintf("%.2f (%.2f-%.2f)",z$report_share_ratio[i],z$ratio_lower[i],z$ratio_upper[i]),"\nq",ps(z$q_value[i])),adj=0,cex=.61,xpd=NA)}
 mtext(note,1,line=3.1,cex=.61)
}
taxa<-c("Staphylococcus aureus","Escherichia coli","Enterococcus faecalis","Enterococcus faecium","Pseudomonas aeruginosa","Bacteroides spp","Candida albicans","Coagulase-negative staphylococci","Selected Klebsiella spp","Enterobacter spp")

# 21. Full procedure-specific ecology, with exact denominators and tested enrichment.
openpdf(21,"procedure_specific_SSI_pathogen_ecology",16,11)
layout(matrix(c(1,2,3,3),2,2,byrow=TRUE),heights=c(3.7,1.3));par(oma=c(2.2,.4,2,.4))
for(k in 1:2){ag<-c("adult","pediatric")[k];g<-d[d$age==ag&d$period=="2018-2021"&d$category!="All surgery types",];cats<-unique(g$category);par(mar=c(5.2,8.2,3,1),cex=.85);empty(c(.5,length(taxa)+.5),c(.4,length(cats)+1.4));pal<-colorRampPalette(c("#EDF4F7",BLUE))(101)
 for(i in seq_along(cats)){yy<-length(cats)+1-i;for(j in seq_along(taxa)){r<-g[g$category==cats[i]&g$pathogen==taxa[j],];x<-j;if(nrow(r)){v<-100*r$proportion[1];rect(x-.45,yy-.38,x+.45,yy+.38,col=pal[1+min(100,round(v*2))],border=NA);tt<-en[en$age==ag&en$period=="2018-2021"&en$category==cats[i]&en$pathogen==taxa[j],];st<-if(nrow(tt)&&tt$q_value<.05)"*"else"";text(x,yy,paste0(sprintf("%.1f",v),st),col=if(v>25)"white"else INK,cex=.66)}else{rect(x-.45,yy-.38,x+.45,yy+.38,col="#E6E6E6",border=NA);text(x,yy,"NR",cex=.6)}};n<-unique(g$total[g$category==cats[i]])[1];text(.35,yy,paste0(cats[i]," (n=",fmt(n),")"),adj=1,cex=.70,xpd=NA)}
 axis(1,1:length(taxa),short(taxa),las=2,tick=FALSE,cex.axis=.7);mtext(paste0(LETTERS[k],"  ",if(k==1)"Adults"else"Pediatrics",", 2018-2021"),3,line=.8,adj=0,font=2,cex=.9);mtext("Pathogen-report share (%)",3,line=-.3,adj=0,cex=.7)
}
par(mar=c(.2,1,.2,1));empty();text(0,.85,"C  Repetition across source periods",adj=0,font=2);text(0,.51,paste0(sum(tolower(rep$same_direction)=="true"&tolower(rep$both_BH_q_below_005)=="true")," of ",nrow(rep)," stable-taxon age/procedure contrasts have the same direction and q<0.05 in both periods."),adj=0,cex=.9);text(0,.18,"* BH q<0.05 for that category versus all other categories in the same age-period source. NR = not separately reported, not zero.",adj=0,cex=.78)
hf("Do procedure groups have distinct and reproducible SSI pathogen profiles?","Separate national source: 378,610 pathogen reports across 2015-2017 and 2018-2021. Marginal-count tests are exploratory; event and hospital clustering are unavailable.");dev.off()

# 22. Effect-size forests for biologically relevant procedure contrasts, not only percentages.
openpdf(22,"procedure_ecology_effect_sizes",16,10)
par(mfrow=c(2,2),oma=c(2.2,.5,2,.5));cats<-c("Abdominal","Orthopedic","Ob/Gyn","Cardiac")
focus<-c("Staphylococcus aureus","Escherichia coli","Enterococcus faecalis","Enterococcus faecium","Pseudomonas aeruginosa","Bacteroides spp","Candida albicans")
for(k in 1:4){g<-po[po$age=="adult"&po$category==cats[k]&po$pathogen%in%focus,];g<-g[match(focus,g$pathogen),];g<-g[!is.na(g$pathogen),];forest(g,paste0(LETTERS[k],"  Adult ",cats[k]," versus other surgery groups"),short(g$pathogen),xlim=c(.05,8))}
hf("Which microbial signals distinguish procedure-specific prevention review?","Pooled disjoint national periods, 369,802 adult SSI pathogen reports. Exact published count marginals; share-ratio CIs and Fisher P with within-family BH q. Stable taxa shown.");dev.off()

# 23. Infection depth is a parallel ecological distinction, not an inferred progression.
openpdf(23,"SSI_depth_specific_pathogen_signals",16,9)
par(mfrow=c(1,2),oma=c(2.2,.4,2,.4));foc<-c("Staphylococcus aureus","Escherichia coli","Enterococcus faecalis","Enterococcus faecium","Pseudomonas aeruginosa","Bacteroides spp","Candida albicans","Coagulase-negative staphylococci","Selected Klebsiella spp","Enterobacter spp")
for(k in 1:2){de<-c("Deep incisional","Organ/space")[k];g<-dt[dt$depth==de&dt$pathogen%in%foc,];g<-g[match(foc,g$pathogen),];g<-g[!is.na(g$pathogen),];forest(g,paste0(LETTERS[k],"  ",de," versus superficial incisional"),short(g$pathogen),xlim=c(.25,4))}
hf("Does SSI depth identify different microbiology and diagnostic-review priorities?","Adult national reports, 2018-2021: superficial 63,988; deep incisional 36,186; organ/space 115,495 pathogen reports. Parallel categories; exploratory count-level tests with BH q.");dev.off()

# 24. Real resistance profiles: retain tested fractions, reported organism count and published significance.
openpdf(24,"procedure_specific_AMR_profiles",16,12)
par(mfrow=c(2,2),oma=c(3,.4,2,.4));amr$phenotype_display<-ifelse(grepl("MRSA",amr$phenotype),"MRSA",ifelse(grepl("VRE",amr$phenotype),"VRE",ifelse(grepl("CRE",amr$phenotype),"CRE",ifelse(grepl("MDR",amr$phenotype),"MDR",ifelse(grepl("Carbapenem",amr$phenotype),"Carbapenem-NS",amr$phenotype)))));phen<-c("MRSA","VRE","CRE","Carbapenem-NS","MDR")
for(k in 1:4){ag<-c("adult","adult","pediatric","pediatric")[k];per<-c("2015-2017","2018-2021","2015-2017","2018-2021")[k];g<-amr[amr$age==ag&amr$period==per&amr$category!="All surgery types",];g<-g[g$phenotype_display%in%phen,];comb<-unique(paste(g$pathogen,g$phenotype_display,sep=" | "));cats<-unique(g$category);par(mar=c(4.6,9.5,3.2,1),cex=.82);empty(c(.5,length(cats)+.5),c(.5,length(comb)+1.2));pal<-colorRampPalette(c("#EDF4F7",PURPLE))(101)
 for(i in seq_along(comb)){yy<-length(comb)+1-i;z<-g[paste(g$pathogen,g$phenotype_display,sep=" | ")==comb[i],];text(.37,yy,gsub("OX/CEFOX/METH ","",gsub("Staphylococcus aureus","S. aureus",gsub("Pseudomonas aeruginosa","P. aeruginosa",gsub("Enterococcus faecium","E. faecium",comb[i],fixed=TRUE),fixed=TRUE),fixed=TRUE),fixed=TRUE),adj=1,cex=.65,xpd=NA);for(j in seq_along(cats)){r<-z[z$category==cats[j],];if(nrow(r)&&is.finite(r$percent_result[1])){v<-r$percent_result[1];rect(j-.43,yy-.34,j+.43,yy+.34,col=pal[1+round(v)],border=NA);st<-if(tolower(r$source_significant_vs_abdominal[1])=="true")"*"else"";text(j,yy+.08,paste0(sprintf("%.1f",v),st),col=if(v>60)"white"else INK,cex=.65);text(j,yy-.18,paste0("T",r$percent_tested[1],"%; N",fmt(r$reported_count[1])),col=if(v>60)"white"else INK,cex=.43)}else{rect(j-.43,yy-.34,j+.43,yy+.34,col="#E5E5E5",border=NA);text(j,yy,"NR",cex=.6)}}}
 axis(1,seq_along(cats),cats,tick=FALSE,las=2,cex.axis=.69);mtext(paste(LETTERS[k],ag,per),3,line=1,adj=0,font=2,cex=.9);mtext("Cell: published phenotype %; T = tested %; N = organism reports",3,line=-.1,adj=0,cex=.64);if(k==2){segments(7.5,.5,7.5,length(comb)+.5,col=GREY,lty=2);mtext("Surgical categories | SSI-depth strata",3,line=-.85,adj=1,cex=.55)}
}
hf("Which resistant phenotypes should procedure-specific stewardship reviews verify locally?","* Source-reported unadjusted mid-P<0.05 versus abdominal surgery, 2015-2017 only. Rounded source percentages; NR = unavailable/suppressed. NS = non-susceptible. Latest adult depth columns are separate strata. Phenotype definitions follow each source period.");dev.off()

# 25. Pediatric ecology + the pathogen-capture gap, with exact event denominators.
openpdf(25,"age_specific_ecology_and_microbiology_capture",16,10)
layout(matrix(c(1,2,3,4),2,2,byrow=TRUE),heights=c(1.2,1));par(oma=c(2.4,.4,2,.4))
for(k in 1:2){cat<-c("Orthopedic","Cardiac")[k];g<-age[age$period=="2018-2021"&age$category==cat&age$pathogen%in%focus,];g<-g[match(focus,g$pathogen),];g<-g[!is.na(g$pathogen),];forest(g,paste0(LETTERS[k],"  Pediatric / adult ",cat),short(g$pathogen),xlim=c(.25,5))}
g<-tot[is.finite(tot$ssi_events_without_pathogen),];par(mar=c(4.8,5.1,2.8,1));plot(0,0,type="n",xlim=c(.5,nrow(g)+.5),ylim=c(0,.35),xaxt="n",xlab="National SSI event populations",ylab="SSI events without a reported pathogen",main="C  Microbiology capture gap")
for(i in 1:nrow(g)){n<-g$ssi_events[i];k<-g$ssi_events_without_pathogen[i];bt<-binom.test(k,n);rect(i-.27,0,i+.27,k/n,col=c(BLUE,ORANGE,PURPLE)[i],border=NA);segments(i,bt$conf.int[1],i,bt$conf.int[2],lwd=1.1);text(i,k/n+.04,paste0(sprintf("%.1f%%",100*k/n),"\n",fmt(k)," / ",fmt(n)),cex=.7)};axis(1,1:nrow(g),paste(g$age,g$period,sep="\n"),cex.axis=.7)
a<-g[g$age=="adult"&g$period=="2015-2017",];b<-g[g$age=="adult"&g$period=="2018-2021",];f<-fisher.test(matrix(c(b$ssi_events_without_pathogen,b$ssi_events_with_pathogen,a$ssi_events_without_pathogen,a$ssi_events_with_pathogen),2,byrow=TRUE));rr<-(b$ssi_events_without_pathogen/b$ssi_events)/(a$ssi_events_without_pathogen/a$ssi_events);se<-sqrt(1/b$ssi_events_without_pathogen-1/b$ssi_events+1/a$ssi_events_without_pathogen-1/a$ssi_events)
par(mar=c(0,1,1,1));empty();text(0,.91,"D  Does an alert expose an actionable evidence gap?",adj=0,font=2);text(0,.66,paste0("Adult missing-pathogen fraction, later / earlier:\nRR ",sprintf("%.3f (%.3f-%.3f)",rr,exp(log(rr)-1.96*se),exp(log(rr)+1.96*se)),"; P",ps(f$p.value)),adj=0,cex=.9);text(0,.27,"A service-level alert can trigger review of specimen collection,\nculture reporting, AST completeness and case ascertainment.\nRecord these as prospective audit outcomes.",adj=0,cex=.83)
write.csv(data.frame(comparison="Adult missing pathogen, 2018-2021 / 2015-2017",RR=rr,lower=exp(log(rr)-1.96*se),upper=exp(log(rr)+1.96*se),p=f$p.value),file.path(T,"microbiology_capture_comparison.csv"),row.names=FALSE)
hf("Do age-specific pathogen signals and incomplete microbiology capture change review priorities?","Separate national source. Panels A-B use exploratory pathogen-report share tests and BH q. C-D use SSI event counts; clustering by source hospital is not recoverable. No missing older pediatric count is invented.");dev.off()

# 26. A priority reversal: conditional AMR percentage versus occurrence among SSI pathogen reports.
openpdf(26,"resistance_percentage_vs_phenotype_review_priority",16,10)
par(mfrow=c(2,2),oma=c(2.6,.4,2,.4));mr<-amr[amr$age=="adult"&amr$period=="2018-2021"&grepl("MRSA",amr$phenotype)&amr$category%in%c("Abdominal","Orthopedic","Ob/Gyn","Cardiac"),];mr<-mr[match(c("Abdominal","Orthopedic","Ob/Gyn","Cardiac"),mr$category),];mo<-oc[oc$age=="adult"&oc$period=="2018-2021"&grepl("MRSA",oc$phenotype)&oc$category%in%mr$category,];mo<-mo[match(mr$category,mo$category),]
for(k in 1:2){par(mar=c(4.5,5.2,2.8,1));vv<-if(k==1)mr$percent_result else mo$organism_share_percent;plot(0,0,type="n",xlim=c(.5,4.5),ylim=c(0,if(k==1)70 else 40),xaxt="n",xlab="Surgical category",ylab=if(k==1)"MRSA among tested S. aureus (%)"else"S. aureus among SSI pathogen reports (%)",main=c("A  Conditional resistance percentage","B  Pathogen composition changes the denominator")[k]);for(i in 1:4){rect(i-.28,0,i+.28,vv[i],col=c(BLUE,ORANGE,GREEN,PURPLE)[i],border=NA);text(i,vv[i]+3,sprintf("%.1f%%",vv[i]),cex=.85)};axis(1,1:4,mr$category,cex.axis=.8)}
par(mar=c(4.5,5.2,2.8,1));lo<-mo$observed_phenotype_per_100_pathogen_reports_min;up<-mo$observed_phenotype_per_100_pathogen_reports_max;plot(0,0,type="n",xlim=c(.5,4.5),ylim=c(0,max(up)*1.3),xaxt="n",xlab="Surgical category",ylab="Observed MRSA per 100 SSI pathogen reports",main="C  Rounding-compatible observed-phenotype range");for(i in 1:4){segments(i,lo[i],i,up[i],lwd=3,col=c(BLUE,ORANGE,GREEN,PURPLE)[i]);points(i,(lo[i]+up[i])/2,pch=16,col=c(BLUE,ORANGE,GREEN,PURPLE)[i]);text(i,up[i]+.9,sprintf("%.3f-%.3f",lo[i],up[i]),cex=.71)};axis(1,1:4,mr$category,cex.axis=.8)
par(mar=c(0,1,1,1));empty();text(0,.91,"D  Translation: rank the review question, not just the percentage",adj=0,font=2,cex=.9)
zz<-en[en$age=="adult"&en$period=="2018-2021"&en$category=="Orthopedic"&en$pathogen=="Staphylococcus aureus",];text(0,.66,paste0("Orthopedic S. aureus share versus other categories:\n",sprintf("RR %.3f (%.3f-%.3f)",zz$report_share_ratio,zz$ratio_lower,zz$ratio_upper),"; q",ps(zz$q_value)),adj=0,cex=.86)
text(0,.29,"Abdominal surgery has the higher MRSA percentage among\ntested S. aureus, while orthopedic reports contain more\nobserved MRSA per 100 reported SSI pathogens.\nThis contrast prioritizes local verification and stewardship review.",adj=0,cex=.83)
hf("Can resistance percentage alone misdirect procedure-specific stewardship review?","National adults, 2018-2021. A-B: published percentage and exact organism-report share. C: derived ranges compatible with rounded published percentages, not exact resistant counts or prophylaxis efficacy.");dev.off()
